function CatHouseCultivationMarketListPopup:FreshFilterNode()
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, UICommonFilterMBNode)
    if nodeEnv == nil then return end
    nodeEnv:SetFilterClass(Constants.UIFilterType.CatHouse)
    nodeEnv:SetCallback(self.catList, Bind(self, self.OnClickFilterNode), Constants.UISortType.CatHouseRally)
    nodeEnv:RestoreState("CatHouseCultivationMarketListPopup", Bind(self, self.OnClickFilterNode))
end

function CatHouseCultivationMarketListPopup:FreshListUI()
    local len     = #self.catList
    local isEmpty = len == 0
    self.selectIndex = not isEmpty and self.selectIndex or nil
    KTool.SetActive(self.MyCatList.gameObject,   not isEmpty)
    KTool.SetActive(self.EmptyNode.gameObject, isEmpty)
    if isEmpty then return end

    local List = self.MyCatList
    if not List.mLoopListView.IsListViewInit then
        List:InitListView(len, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(List, len)
    end
end

function CatHouseCultivationMarketListPopup:OnGetItemByIndex(cell, index)
    if index < 0 then
        return nil
    end

    ---@type CatHouseListBtnNode
    local nodeEnv = CfUtils.GetLuaScr(cell, CellEnvPath)
    if isNull(nodeEnv) then return nil end
    
    local position         = index + 1
    nodeEnv:SetCallback(function (catData)
        self:OnClickCatNodeAction(catData, position)
    end)
    
    nodeEnv:FreshCommonUI(self.catList[position], true)
    nodeEnv:FreshRallyUI(self.goodsId)

    return cell

end

---SwitchCatSelectShowState
---刷新猫选择显示状态
function CatHouseCultivationMarketListPopup:SwitchCatSelectShowState()
    local isSelect = self.selectIndex ~= nil
    KTool.SetActive(self.NoSelect.gameObject,         not isSelect)
    KTool.SetActive(self.CatHouseTipsNode.gameObject, isSelect)

end

function CatHouseCultivationMarketListPopup:CheckRallyCat(catData, cb)
    local id = checkNumber(catData.id)
    if id <= 0 then
        cb(nil)
        return
    end
    local requestParams = {
        rallyPlayerId = catData.playerId,
        rallyPlayerCatId = id,

    }
    table.merge(self:GenerateRequestParams(), requestParams)
    GameUtils.Request(Interfaces.CatHouseRallyCatCheck, requestParams or {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        
        local catList = checkTable(response.data.catList)
        cb(catList)
    end)
end

function CatHouseCultivationMarketListPopup:GenerateRequestParams()
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, UICommonFilterMBNode)
    if nodeEnv == nil then return end
    local groups    = nodeEnv:GetGroups()
    local geneIdDic = nodeEnv:GetGeneIdDic()
    local requestParams = {}
    local catTypeList = groups[tostring(Constants.ScreenType.CatType)] or {}
    if next(catTypeList) ~= nil then
        requestParams.petIds = table.concat(catTypeList, ",")
    end
    local geneTypeList = groups[tostring(Constants.ScreenType.CatDataType)] or {}
    if next(geneTypeList) ~= nil then
        requestParams.geneTypeIds = table.concat(geneTypeList, ",")
    end
    if next(geneIdDic) ~= nil then
        local t = {}
        for k, v in pairs(geneIdDic) do
            for _, vv in pairs(v) do
                table.insert(t, vv)
            end 
        end
        requestParams.geneIds = table.concat(t, ",")
    end
    -- print(table.toString(groups))
    -- print(table.toString(geneIdDic))
    -- print(table.toString(requestParams))
    return requestParams
end


function CatHouseCultivationMarketListPopup:FreshFilterData(dataList)
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, UICommonFilterMBNode)
    if not isNull(nodeEnv) then
        nodeEnv:SetOriginData(dataList)
        nodeEnv:SetFilterData(dataList)
        
    end
end

