function CatHouseCultivationMarketListPopup:OnClickBtnRefreshAction()
    local requestParams = self:GenerateRequestParams()
    CatHouseMgr:RequestRallyCats(requestParams, function (dataList)
        self:FreshFilterData(dataList)
        
    end)
end

function CatHouseCultivationMarketListPopup:OnClickFilterNode(dataList, isFilter)
    if isFilter then
        if next(dataList) == nil then
            GameUtils.Toast(localize("当前没有符合要求的猫咪"))
        end
        self.selectIndex = nil
    end
    self.catList = dataList

    self:FreshListUI()
    self:SwitchCatSelectShowState()

end

function CatHouseCultivationMarketListPopup:OnClickCatNodeAction(catData, index)
    ---@type CatHouseTipsNode
    local env = CfUtils.GetLuaScr(self.CatHouseTipsNode, "Game.CatHouse.CatHouseTipsNode")
    if isNull(env) then
        return
    end

    local isSwitchState = self.selectIndex == nil
    self.selectIndex = index
    if isSwitchState then
        self:SwitchCatSelectShowState()
    end

    local geneId      = self.geneId
    local isOwnGeneId = geneId > 0
    local extraParams
    if isOwnGeneId then
        extraParams = { geneId = geneId }
    end
    env:FreshUI(catData, ViewType, function()
        self:CheckRallyCat(catData, function (catList)
            local isFail = catList ~= nil and next(catList) ~= nil
            if isFail then
                GameUtils.Toast(localize("当前猫球已被他人选择孵化"))
                catList = CatHouseMgr:GetInstance():GenerateRallyList(catList, 0)
                --- 更新列表
                self:FreshFilterData(catList)
            else
                KCookie.Set(CookieOtherCatInfoName, {otherCatData = catData, otherCatOwnerInfo = {playerId = catData.playerId}, consumePrice = catData.price, matchType = 3})
                ---因为猫屋主界面常驻 所以 如果想清除记录的话必须移动记录到 UIHomeView
                local moveToRecordId = isOwnGeneId and Constants.UITypeIds.UIHomeView or nil
                CatHouseMgr:GetInstance():BackToMatchPopup(isOwnGeneId, isOwnGeneId, false, nil, moveToRecordId)
            end
        end)

    end, extraParams)

end

